/**
 * @fileoverview Node "Mail aufbereiten": holt Absender, Betreff, Text und die
 * IMAP-UID aus der eingegangenen Mail und baut daraus den Text, den die
 * KI-Analyse auswertet.
 *
 * Ausgabe: ein Item je eingegangener Mail mit den Feldern uid, absenderMail,
 * absenderName, betreff und mailText.
 */

/**
 * Liest Mailadresse und Anzeigename aus dem "from"-Feld einer Mail.
 * Die IMAP-Node liefert ein Objekt ({ value: [{ address, name }], text, html });
 * aeltere Formate liefern einen reinen String wie 'Max <max@example.org>' -
 * beides wird unterstuetzt.
 *
 * @param {{value?: Array<{address?: string, name?: string}>}|string|null|undefined} feld
 *   Das "from"-Feld der Mail.
 * @returns {{mail: string, name: string}} Kleingeschriebene Mailadresse und
 *   Anzeigename; beide leer, wenn das Feld fehlt.
 */
function absenderAus(feld) {
  if (!feld) return { mail: '', name: '' };
  if (typeof feld === 'string') {
    const treffer = feld.match(/<([^>]+)>/);
    return {
      mail: (treffer ? treffer[1] : feld).trim().toLowerCase(),
      name: feld.replace(/<[^>]*>/, '').replace(/"/g, '').trim()
    };
  }
  const erster = Array.isArray(feld.value) && feld.value[0] ? feld.value[0] : {};
  return {
    mail: String(erster.address || '').trim().toLowerCase(),
    name: String(erster.name || '').trim()
  };
}

const mail = $json;
const absender = absenderAus(mail.from);
const betreff = String(mail.subject || '').trim();
// UID der Nachricht im Postfach - wird zum Verschieben in Ordner gebraucht
const uid = mail?.attributes?.uid ?? null;
const text = String(mail.text || mail.textAsHtml || '').trim().slice(0, 6000);
// Heutiges Datum im JJJJ-MM-TT-Format, damit die KI-Analyse relative
// Zeitangaben wie naechsten Freitag oder in zwei Wochen berechnen kann.
const heute = new Date().toISOString().slice(0, 10);

return {
  json: {
    uid,
    absenderMail: absender.mail,
    absenderName: absender.name,
    betreff,
    mailText: `Heutiges Datum: ${heute}\nVon: ${absender.mail}\nBetreff: ${betreff}\n\n${text}`
  }
};

