/**
 * @fileoverview Node "Bestaetigung vorbereiten": baut die Bestaetigungsmail an
 * den Absender, nachdem sein Ticket angelegt wurde.
 *
 * Liest die Ticketdaten aus dem EIGENEN Eingangs-Item statt sie ueber die
 * Position aus einem fruehen Baustein zu erraten. Dieses Item kommt vom
 * IF-Baustein "Ticket erfolgreich geschrieben?" (Erfolgs-Ausgang) und
 * enthaelt dank "Ticket-Ergebnis anreichern" bereits beides: die
 * Ticketdaten UND das Schreibergebnis. Das haelt die Zuordnung auch dann
 * richtig, wenn in einem Lauf mehrere Mails ankommen und nur ein Teil davon
 * erfolgreich geschrieben wird: Wuerde stattdessen ueber die Position in
 * einem frueheren Baustein zugeordnet, bekaeme nach dem ersten Fehlschlag
 * jeder folgende Absender die Bestaetigung fuer ein fremdes Ticket.
 *
 * Ausgabe: ein Item je zu versendender Mail mit an, betreff und text.
 */
const eigenesPostfach = String($env.JOIN_MAIL_USER || '').toLowerCase();

const ergebnisse = [];
for (let i = 0; i < items.length; i++) {
  const quelle = items[i].json;
  if (!quelle || !quelle.ticket) continue;

  // SCHUTZ VOR ENDLOSSCHLEIFE: Niemals an das eigene Postfach antworten.
  // Sonst loest die Antwort den Workflow erneut aus - endlos.
  if (String(quelle.absenderMail || '').toLowerCase() === eigenesPostfach) continue;

  const teilaufgaben = Array.isArray(quelle.ticket.subtasks) ? quelle.ticket.subtasks : [];

  ergebnisse.push({ json: {
    an: quelle.absenderMail,
    betreff: `Ihre Anfrage ist angekommen: ${quelle.ticket.title}`,
    text: [
      'Hallo,',
      '',
      'vielen Dank fuer Ihre Nachricht. Wir haben daraus ein Ticket erstellt:',
      '',
      `  Titel:       ${quelle.ticket.title}`,
      `  Einstufung:  ${quelle.ticket.category === 'technical' ? 'Technische Aufgabe' : 'Feature-Wunsch'}`,
      `  Prioritaet:  ${quelle.ticket.priority}`,
      quelle.ticket.date ? `  Faellig bis: ${quelle.ticket.date}` : '  Faellig bis: nicht angegeben',
      ...(teilaufgaben.length ? ['  Teilaufgaben:', ...teilaufgaben.map((t) => `    - ${t.text}`)] : []),
      '',
      'Das Ticket liegt jetzt in unserer Triage-Spalte und wird dort gesichtet.',
      'Sobald es sich bewegt, melden wir uns erneut.',
      '',
      'Hinweis: Diese Nachricht wurde automatisch erzeugt.',
      teilaufgaben.length
        ? 'Titel, Einstufung und Teilaufgaben stammen aus einer KI-Analyse Ihrer Mail.'
        : 'Titel und Einstufung stammen aus einer KI-Analyse Ihrer Mail.',
    ].join('\n')
  }});
}
return ergebnisse;

/**
 * @fileoverview Node "Fehlerhinweis vorbereiten": baut den Hinweis an den
 * Absender, wenn die automatische Verarbeitung scheiterte. Die Items der
 * Fehlerausgaenge fuehren die Absenderadresse mit.
 *
 * Ausgabe: ein Item je zu versendender Mail mit an, betreff und text.
 */
const eigenesPostfach = String($env.JOIN_MAIL_USER || '').toLowerCase();

const ergebnisse = [];
for (const item of items) {
  const an = String(item.json.absenderMail || '').toLowerCase();
  if (!an) continue;
  // Schutz vor Endlosschleife (siehe Bestaetigungs-Node)
  if (an === eigenesPostfach) continue;

  ergebnisse.push({ json: {
    an,
    betreff: 'Ihre Nachricht ist angekommen',
    text: [
      'Hallo,',
      '',
      'wir haben Ihre Nachricht erhalten. Die automatische Verarbeitung hat',
      'diesmal nicht funktioniert, deshalb schaut sich jemand aus dem Team',
      'Ihre Anfrage persoenlich an und meldet sich zeitnah bei Ihnen.',
      '',
      'Es geht nichts verloren - Ihre Mail ist bei uns gespeichert.',
      '',
      'Hinweis: Diese Nachricht wurde automatisch erzeugt.',
    ].join('\n')
  }});
}
return ergebnisse;

/**
 * @fileoverview Node "Innerhalb Tageslimit": laesst nur die Mails durch, die
 * heute noch in das Tageslimit passen. Die Pruefung laeuft VOR der KI-Analyse,
 * damit eine abgewiesene Mail gar kein KI-Kontingent kostet.
 *
 * Gezaehlt werden die Tickets selbst statt eines separaten Zaehlers, der
 * auseinanderlaufen koennte: KI-Tickets sind an creator.type "extern"
 * erkennbar, das Anlegedatum steckt als Zeitstempel in der id.
 *
 * Ausgabe: ein Item je durchgelassener Mail, ergaenzt um platzNr.
 */
const TAGESLIMIT = 10;

const roh = $json.data ?? $json;
const alleTickets = (roh && typeof roh === 'object') ? Object.values(roh) : [];

const tagesbeginn = new Date();
tagesbeginn.setHours(0, 0, 0, 0);
const grenze = tagesbeginn.getTime();

const heuteSchon = alleTickets.filter((t) =>
  t && typeof t === 'object' &&
  t.creator && t.creator.type === 'extern' &&
  Number(t.id) >= grenze
).length;

const mails = $('Mail aufbereiten').all();

// Jede wartende Mail belegt einen Platz. Position i bekommt Platz
// heuteSchon + i - dadurch greift das Limit auch bei mehreren Mails
// im selben Durchlauf korrekt.
const ergebnisse = [];
for (let i = 0; i < mails.length; i++) {
  if (heuteSchon + i >= TAGESLIMIT) continue;
  ergebnisse.push({ json: { ...mails[i].json, platzNr: heuteSchon + i + 1 } });
}
return ergebnisse;

/**
 * @fileoverview Node "Ueber Tageslimit": Gegenstueck zu
 * "Innerhalb Tageslimit" - gibt genau die Mails aus, die heute nicht mehr in
 * das Limit passen. Sie bekommen einen Hinweis per Mail statt eines Tickets.
 *
 * Gezaehlt wird nach derselben Regel wie im Gegenstueck: die Tickets selbst,
 * erkennbar an creator.type "extern", mit dem Anlegedatum als Zeitstempel in
 * der id.
 *
 * Ausgabe: ein Item je abgewiesener Mail, ergaenzt um heuteSchon und limit.
 */
const TAGESLIMIT = 10;

const roh = $json.data ?? $json;
const alleTickets = (roh && typeof roh === 'object') ? Object.values(roh) : [];

const tagesbeginn = new Date();
tagesbeginn.setHours(0, 0, 0, 0);
const grenze = tagesbeginn.getTime();

const heuteSchon = alleTickets.filter((t) =>
  t && typeof t === 'object' &&
  t.creator && t.creator.type === 'extern' &&
  Number(t.id) >= grenze
).length;

const mails = $('Mail aufbereiten').all();

// Gegenstueck: alles, was ueber dem Tageslimit liegt.
const ergebnisse = [];
for (let i = 0; i < mails.length; i++) {
  if (heuteSchon + i < TAGESLIMIT) continue;
  ergebnisse.push({ json: { ...mails[i].json, heuteSchon, limit: TAGESLIMIT } });
}
return ergebnisse;

/**
 * @fileoverview Node "Limit-Hinweis vorbereiten": baut die Mail, die dem
 * Absender das erreichte Tageslimit erklaert, damit seine Nachricht nicht
 * kommentarlos liegen bleibt.
 *
 * Ausgabe: ein Item je zu versendender Mail mit an, betreff und text.
 */
const eigenesPostfach = String($env.JOIN_MAIL_USER || '').toLowerCase();
const ergebnisse = [];
for (const item of items) {
  const an = String(item.json.absenderMail || '').toLowerCase();
  if (!an || an === eigenesPostfach) continue;   // Schutz vor Endlosschleife
  ergebnisse.push({ json: {
    an,
    betreff: 'Tageslimit erreicht - Ihre Anfrage kam an',
    text: [
      'Hallo,',
      '',
      `fuer heute ist das Limit von ${item.json.limit} automatisch erstellten`,
      'Anfragen erreicht. Ihre Nachricht ist bei uns angekommen, es wurde aber',
      'noch kein Ticket daraus erzeugt.',
      '',
      'Das Limit schuetzt vor unerwartet hohen Kosten der KI-Auswertung.',
      'Bitte schicken Sie Ihre Anfrage morgen noch einmal - oder warten Sie',
      'kurz ab, jemand aus dem Team sieht die Nachricht ohnehin.',
      '',
      'Hinweis: Diese Nachricht wurde automatisch erzeugt.',
    ].join('\n')
  }});
}
return ergebnisse;

const tls = require('tls');

/**
 * Verschiebt eine E-Mail per IMAP in einen anderen Ordner.
 * Nutzt nur das eingebaute tls-Modul - Dateizugriff ist in dieser
 * n8n-Instanz bewusst gesperrt.
 */
function mailVerschieben(zugang, uid, zielordner, quellordner) {
  return new Promise((resolve, reject) => {
    const socket = tls.connect(
      { host: zugang.host, port: Number(zugang.port) || 993, servername: zugang.host },
      () => {}
    );
    socket.setEncoding('utf8');
    socket.setTimeout(20000);

    let puffer = '';
    let schritt = 0;
    const q = (wert) => `"${String(wert).replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;
    const befehle = [
      { tag: 'a1', cmd: `a1 LOGIN ${q(zugang.user)} ${q(zugang.passwort)}` },
      { tag: 'a2', cmd: `a2 SELECT ${q(quellordner)}` },
      { tag: 'a3', cmd: `a3 UID MOVE ${Number(uid)} ${q(zielordner)}` },
      { tag: 'a4', cmd: 'a4 LOGOUT' },
    ];

    const abbrechen = (fehler) => { try { socket.destroy(); } catch (e) {} reject(fehler); };
    socket.on('timeout', () => abbrechen(new Error('IMAP-Zeitueberschreitung')));
    socket.on('error', (e) => abbrechen(e));

    socket.on('data', (teil) => {
      puffer += teil;
      if (schritt === 0) {
        if (!/^\* OK/m.test(puffer)) return;
        puffer = ''; socket.write(befehle[0].cmd + '\r\n'); schritt = 1; return;
      }
      const aktuell = befehle[schritt - 1];
      const antwort = new RegExp(`^${aktuell.tag} (OK|NO|BAD)(.*)$`, 'm').exec(puffer);
      if (!antwort) return;
      if (antwort[1] !== 'OK') {
        return abbrechen(new Error(`IMAP ${aktuell.tag}: ${antwort[1]}${antwort[2]}`));
      }
      // Ein blosses OK beweist nichts: bei unbekannter UID meldet der Server
      // ebenfalls OK. Nur COPYUID/EXPUNGE belegen den echten Umzug.
      if (aktuell.tag === 'a3' && !/COPYUID|EXPUNGE/.test(puffer)) {
        return abbrechen(new Error(`Nachricht UID ${uid} nicht gefunden - nichts verschoben`));
      }
      puffer = '';
      if (schritt >= befehle.length) { socket.end(); return resolve(true); }
      socket.write(befehle[schritt].cmd + '\r\n'); schritt += 1;
    });
  });
}

const zugang = {
  host: $env.JOIN_MAIL_HOST,
  port: $env.JOIN_MAIL_PORT,
  user: $env.JOIN_MAIL_USER,
  passwort: $env.JOIN_MAIL_PASSWORD,
};

// Ueber dem Limit abgewiesene Mails sind korrekt behandelt (Absender wurde
// informiert), deshalb gelten sie als erledigt.
const ergebnisse = [];
for (const item of items) {
  const uid = item.json.uid;
  if (!uid) { ergebnisse.push({ json: { verschoben: false, grund: 'keine UID' } }); continue; }
  try {
    await mailVerschieben(zugang, uid, 'erledigt', 'INBOX');
    ergebnisse.push({ json: { verschoben: true, uid, ordner: 'erledigt', grund: 'Tageslimit' } });
  } catch (f) {
    ergebnisse.push({ json: { verschoben: false, uid, fehler: String(f.message) } });
  }
}
return ergebnisse;
